    'queue_reports.help_body' => 'Kuyruğa giren her çağrı bir kez sayılır. <b>Cevaplanan</b>: bir temsilciye bağlandı. <b>Kaybedilen</b>: arayan beklerken kapattı ya da kuyruk süresi doldu. <b>Kısa terk</b>: %d saniyeden kısa bekleyip kapatanlar; hizmet seviyesine katılmaz. <b>Hizmet seviyesi</b>: hedef sürede cevaplanan çağrıların, kısa terkler hariç tüm çağrılara oranı. <b>ASA</b>: cevaplanan çağrılarda ortalama bekleme. <b>AHT</b>: ortalama konuşma süresi. <b>Cevaplama oranı</b> (temsilci): kuyruk temsilciyi çaldırdığında ne sıklıkla açtığı. <b>Geri dönüş</b>: kayıp çağrının numarası daha sonra bir dahiliden arandıysa ya da aynı numara tekrar arayıp cevaplandıysa çözülmüş sayılır. Veriler Asterisk kuyruk günlüğünden gelir; rapor PDF veya Excel olarak indirilebilir.',
