    'ai_tts.tab_providers' => 'Sağlayıcılar',
    'ai_tts.providers_text' => 'Kullanmak istediğiniz servisin erişim bilgilerini girin. Gizli anahtarlar şifrelenerek saklanır; boş bırakılırsa kayıtlı anahtar korunur.',
